function measure(node):
    if node is null: return (0, true)
    leftHeight, leftOK = measure(node.left)
    rightHeight, rightOK = measure(node.right)
    balanced = leftOK and rightOK and abs(leftHeight - rightHeight) <= 1
    return (1 + max(leftHeight, rightHeight), balanced)
